	$(".onlinedemo_btn").click(function(){		
		$(".error_msg").html("");
		var error = 0;
		var first_name = $("#first_name").val();
		var last_name = $("#last_name").val();
		var email = $("#email").val();
		var phone = $("#phone").val();
		var title = $("#title").val();
		var company = $("#company").val();
		
		if(first_name == ""){
			$("#error_first_name").html("The field is required.");
			error = 1;
		}
		if(last_name == ""){
			$("#error_last_name").html("The field is required.");
			error = 1;
		}
		if(email == ""){
			$("#error_email_name").html("The field is required.");
			error = 1;
		}
		else if(IsEmail(email)==false){
			$("#error_email_name").html("The e-mail address entered is invalid.");
			error = 1;
		}
		
		if(phone == ""){
			$("#error_phone_name").html("The field is required.");
			error = 1;
		}
		else if(validatePhone(phone) == false){
			$("#error_phone_name").html("Phone number is invalid.");
			error = 1;
		}
		if(title == ""){
			$("#error_title_name").html("The field is required.");
			error = 1;
		}
		if(company == ""){
			$("#error_company_name").html("The field is required.");
			error = 1;
		}
		if(error == 1){
			$('html, body').animate({
				scrollTop: $("#first_name").offset().top-150
			}, 1000);
			
			return false;
		}
		else{
		    $("form[name='personalizedemo']").submit();
		}
	});
	
