	function delete_cookie(name) {	//to delete cookie and reset form -- yet to be finished with functionality
  document.cookie = name +'=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT;';
}
	
	function setCookie(cname, cvalue, exdays) {		// setting cookie 
		var d = new Date();
		d.setTime(d.getTime() + (exdays *  24 *  60 *  60 *  1000));
		var expires = "expires="+d.toUTCString();
		document.cookie = cname + "=" + cvalue + ";" + expires + ";path=/";
		
	}
	
	function getCookie(cname) {		//getting cookie using cookie name
		var name = cname + "=";
		
		var decodedCookie = decodeURIComponent(document.cookie);
		var ca = decodedCookie.split(';');
		for(var i = 0; i < ca.length; i++) {
			var c = ca[i];
			while (c.charAt(0) == ' ') {
				c = c.substring(1);
			}
			if (c.indexOf(name) == 0) {
				return c.substring(name.length, c.length);
			}
		}
		return "";
	}
	

	
